const body = $json.body || $json;

const systemPrompt = `Tu es le module de classification d'intention de l'assistant IA de Darimmo, une plateforme marocaine d'annonces immobilieres.

Ta seule tache : analyser le message de l'utilisateur et l'historique de conversation, puis renvoyer UNIQUEMENT un objet JSON valide au format :
{
  "intent": "<une des 9 valeurs>",
  "confidence": <0.0 a 1.0>,
  "entities": { ... },
  "needs_clarification": <bool>,
  "clarification_question": <string ou null>
}

Intentions possibles : search_property, create_listing, update_listing, delete_listing, my_listings, payment_status, contact_owner, account_help, general_help, unknown.

Distinction importante entre account_help et general_help :
- account_help : questions sur LE COMPTE PERSONNEL de l'utilisateur deja existant (mes preferences, mes favoris, mes infos de profil). Suppose generalement que l'utilisateur est deja inscrit.
- general_help : questions sur le fonctionnement general de la plateforme (comment creer un compte, comment publier une annonce fonctionne, questions d'un visiteur non inscrit, FAQ generale).

Regles strictes :
- N'invente JAMAIS une entite qui n'est pas explicitement dans le message ou l'historique. Une entite absente = null, jamais une supposition.
- Si le message est ambigu ou hors sujet Darimmo, utilise "unknown".
- Si la confiance est inferieure a 0.6, mets needs_clarification a true et propose une question de clarification courte et polie.
- Ne reponds jamais avec du texte hors du JSON.`;

const historyText = (body.conversation_history || [])
  .map(m => `${m.sender}: ${m.content}`)
  .join('\n');

const userContextText = JSON.stringify(body.user_context || {});

const fullPrompt = `${systemPrompt}\n\nContexte utilisateur : ${userContextText}\n\nHistorique de conversation :\n${historyText}\n\nMessage actuel de l'utilisateur : "${body.message}"`;

const geminiRequestBody = {
  contents: [{ parts: [{ text: fullPrompt }] }],
  generationConfig: {
    responseMimeType: "application/json",
    responseSchema: {
      type: "OBJECT",
      properties: {
        intent: { type: "STRING", enum: ["search_property","create_listing","update_listing","delete_listing","my_listings","payment_status","contact_owner","account_help","general_help","unknown"] },
        confidence: { type: "NUMBER" },
        entities: {
          type: "OBJECT",
          properties: {
            city: { type: "STRING", nullable: true },
            property_type: { type: "STRING", nullable: true },
            transaction_type: { type: "STRING", nullable: true },
            budget_max: { type: "NUMBER", nullable: true },
            budget_min: { type: "NUMBER", nullable: true },
            bedrooms_min: { type: "NUMBER", nullable: true },
            has_pool: { type: "BOOLEAN", nullable: true },
            has_parking: { type: "BOOLEAN", nullable: true },
            has_garden: { type: "BOOLEAN", nullable: true },
            annonce_id: { type: "STRING", nullable: true }
          }
        },
        needs_clarification: { type: "BOOLEAN" },
        clarification_question: { type: "STRING", nullable: true }
      },
      required: ["intent","confidence","entities","needs_clarification"]
    }
  }
};

return {
  json: {
    session_id: body.session_id,
    auth_token: body.auth_token || '',
    user_context: body.user_context || {},
    original_message: body.message,
    gemini_request_body: geminiRequestBody
  }
};

let classification;
try {
  const rawText = $json.candidates[0].content.parts[0].text;
  classification = JSON.parse(rawText);
} catch (e) {
  classification = {
    intent: 'unknown',
    confidence: 0,
    entities: {},
    needs_clarification: true,
    clarification_question: "Je n'ai pas bien compris votre demande, pouvez-vous reformuler ?"
  };
}

if (classification.confidence < 0.6) {
  classification.needs_clarification = true;
  if (!classification.clarification_question) {
    classification.clarification_question = "Pouvez-vous preciser votre demande ?";
  }
}

const prev = $('Build Classification Prompt').item.json;

// Si clarification necessaire, on route directement vers une reponse,
// peu importe l'intent detecte.
const effectiveIntent = classification.needs_clarification ? 'needs_clarification' : classification.intent;

return {
  json: {
    session_id: prev.session_id,
    original_message: prev.original_message,
    intent: classification.intent,
    effective_intent: effectiveIntent,
    confidence: classification.confidence,
    entities: classification.entities,
    needs_clarification: classification.needs_clarification,
    clarification_question: classification.clarification_question,
    llm_calls_count: 1
  }
};
